/**
 * IDE / 终端的品牌图标（内联 SVG）。
 *
 * 为什么不走 Iconify 在线 API：离线与首屏稳定性不可控，而这些图标体量很小，
 * 内联后随构建产物打包，不产生额外网络请求。
 *
 * 数据来源：logos（Iconify 官方集合，官方彩色 logo：JetBrains 系 / Xcode /
 * Sublime）与 simple-icons（单色品牌标记）。品牌本身即为彩色（蓝/绿/渐变）
 * 的直接用官方彩色版；品牌本身就是单一深色的（Cursor / Windsurf / iTerm）
 * 用 currentColor 跟随明暗主题，亮色下深色、暗色下白色，避免暗色背景上隐形。
 */
export interface BrandIcon {
  /** 与图标原始画布一致的 viewBox，保证不同来源的图标视觉大小一致 */
  viewBox: string;
  /** SVG 内部标记（不含外层 <svg>），交由 v-html 渲染 */
  body: string;
}

