/**
 * 取某个工具的图标，并把 SVG 内部的 id 变成全局唯一。
 *
 * 为什么需要去重：VS Code / IDEA 的图标用 <defs> 定义渐变和 mask，这些 id 在
 * DOM 里是全局的；同一张图在列表里出现多次时（多个项目用同一个 IDE），重复 id
 * 会让 url(#…) 引用互串（虽内容相同，但一旦将来改成不同着色就会串色）。
 * 这里只改 id 定义与三处引用写法，不触碰路径数据。
 *
 * 计数器放在模块作用域（而不是组件内），否则每个组件实例都从 0 开始、
 * 生成的后缀会重复。
 */
let iconSeq = 0;

export function getBrandIcon(toolId: string): BrandIcon | null {
  const raw = brandIcons[toolId];
  if (!raw) return null;
  if (!raw.body.includes('id="')) return raw;

  const suffix = `-i${++iconSeq}`;
  const body = raw.body
    .replace(/(id=")([\w-]+)"/g, (_m, p1: string, p2: string) => `${p1}${p2}${suffix}"`)
    .replace(/(href="#)([\w-]+)"/g, (_m, p1: string, p2: string) => `${p1}${p2}${suffix}"`)
    .replace(/(url\(#)([\w-]+)\)/g, (_m, p1: string, p2: string) => `${p1}${p2}${suffix})`);
  return { viewBox: raw.viewBox, body };
}
